"""Turn a content directory into a built site."""

import html
import re
import tomllib
from dataclasses import dataclass, field
from pathlib import Path
from string import Template

from quillmark import frontmatter, markdown

DEFAULT_CONFIG = {"title": "Untitled site", "base_url": "", "author": ""}


@dataclass
class Post:
    slug: str
    title: str
    date: str
    html: str
    meta: dict[str, str] = field(default_factory=dict)


def slugify(text: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return slug or "untitled"


def load_config(root: Path) -> dict[str, str]:
    config = dict(DEFAULT_CONFIG)
    path = root / "site.toml"
    if path.exists():
        with path.open("rb") as fh:
            config.update(tomllib.load(fh))
    return config


def load_post(path: Path) -> Post:
    meta, body = frontmatter.split(path.read_text(encoding="utf-8"))
    title = meta.get("title") or _first_heading(body) or path.stem.replace("-", " ").title()
    return Post(
        slug=meta.get("slug") or slugify(path.stem),
        title=title,
        date=meta.get("date", ""),
        html=markdown.to_html(body),
        meta=meta,
    )


def _first_heading(body: str) -> str | None:
    for line in body.splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return None


def load_posts(content: Path) -> list[Post]:
    posts = [load_post(p) for p in sorted(content.glob("*.md"))]
    return sorted(posts, key=lambda p: p.date, reverse=True)


def render_index(template: Template, config: dict[str, str], posts: list[Post]) -> str:
    items = "\n".join(
        f'    <li><a href="{p.slug}.html">{html.escape(p.title)}</a>'
        f' <time datetime="{p.date}">{p.date}</time></li>'
        for p in posts
    )
    return template.substitute(site_title=html.escape(config["title"]), posts=items)


def render_post(template: Template, config: dict[str, str], post: Post) -> str:
    return template.substitute(
        site_title=html.escape(config["title"]),
        title=html.escape(post.title),
        date=post.date,
        author=html.escape(post.meta.get("author", config["author"])),
        content=post.html,
    )


def build(root: Path, out: Path | None = None) -> list[Path]:
    root = Path(root)
    out = Path(out) if out else root / "public"
    config = load_config(root)
    templates = root / "templates"
    post_tpl = Template((templates / "post.html").read_text(encoding="utf-8"))
    index_tpl = Template((templates / "index.html").read_text(encoding="utf-8"))

    posts = load_posts(root / "content")
    out.mkdir(parents=True, exist_ok=True)

    written = []
    for post in posts:
        target = out / f"{post.slug}.html"
        target.write_text(render_post(post_tpl, config, post), encoding="utf-8")
        written.append(target)

    index = out / "index.html"
    index.write_text(render_index(index_tpl, config, posts), encoding="utf-8")
    written.append(index)
    return written
"""Split a document into its front-matter block and its body.

A front-matter block is a run of ``key: value`` lines fenced by ``---``
at the very top of the file.
"""

FENCE = "---"


class FrontMatterError(ValueError):
    pass


def split(text: str) -> tuple[dict[str, str], str]:
    if not text.startswith(FENCE + "\n"):
        return {}, text

    end = text.find("\n" + FENCE + "\n", len(FENCE))
    if end == -1:
        raise FrontMatterError("front matter is never closed with '---'")

    meta: dict[str, str] = {}
    for number, line in enumerate(text[len(FENCE) + 1 : end].splitlines(), start=2):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, sep, value = line.partition(":")
        if not sep or not key.strip():
            raise FrontMatterError(f"line {number}: expected 'key: value', got {line!r}")
        meta[key.strip().lower()] = value.strip()

    body = text[end + len(FENCE) + 2 :]
    return meta, body
from pathlib import Path

import pytest

from quillmark.site import build, slugify

ROOT = Path(__file__).resolve().parent.parent


@pytest.mark.parametrize(
    ("text", "expected"),
    [("Hello, World!", "hello-world"), ("  spaced  out ", "spaced-out"), ("???", "untitled")],
)
def test_slugify(text, expected):
    assert slugify(text) == expected


@pytest.fixture(scope="module")
def out(tmp_path_factory):
    out = tmp_path_factory.mktemp("public")
    build(ROOT, out)
    return out


class TestWhenBuildingTheSampleSite:
    def test_it_should_write_one_page_per_post_and_an_index(self, out):
        assert sorted(p.name for p in out.iterdir()) == [
            "hello-quillmark.html",
            "index.html",
            "tide-tables-by-hand.html",
        ]

    def test_it_should_list_the_newest_post_first(self, out):
        index = (out / "index.html").read_text()
        assert index.index("tide-tables-by-hand") < index.index("hello-quillmark")

    def test_it_should_use_the_site_title(self, out):
        assert "<title>Field Notes</title>" in (out / "index.html").read_text()

    def test_it_should_prefer_the_post_author_over_the_site_author(self, out):
        assert "M. Trevose" in (out / "tide-tables-by-hand.html").read_text()

    def test_it_should_escape_titles(self, out):
        assert "Hello, quillmark · Field Notes" in (out / "hello-quillmark.html").read_text()
from quillmark.cli import main


class TestWhenStartingANewPost:
    def test_it_should_write_front_matter_with_the_title_and_date(self, tmp_path):
        main(["--root", str(tmp_path), "new", "Fog Signals", "--date", "2026-10-01"])
        text = (tmp_path / "content" / "fog-signals.md").read_text()
        assert text == "---\ntitle: Fog Signals\ndate: 2026-10-01\n---\n\n"

    def test_and_the_post_exists_it_should_refuse(self, tmp_path):
        main(["--root", str(tmp_path), "new", "Twice"])
        assert main(["--root", str(tmp_path), "new", "Twice"]) == 1


class TestWhenAPostHasBrokenFrontMatter:
    def test_it_should_exit_nonzero(self, tmp_path, capsys):
        (tmp_path / "content").mkdir()
        (tmp_path / "templates").mkdir()
        for name in ("post.html", "index.html"):
            (tmp_path / "templates" / name).write_text("$site_title")
        (tmp_path / "content" / "bad.md").write_text("---\ntitle: never closed\n")
        assert main(["--root", str(tmp_path), "build"]) == 1

